// Pixel-Art: grobe Bloecke + reduzierte Palette — die Blockgroesse
// pulsiert leicht mit dem Beat.
vec4 farbe(vec2 uv, vec4 src)
{
    float block = 96.0 - 24.0 * beat;                    // Bloecke je Bildhoehe
    vec2 raster = vec2(block * uResolution.x / uResolution.y, block);
    vec2 mitte = (floor(uv * raster) + 0.5) / raster;
    vec3 farbe = texture(uTex, mitte).rgb;
    float stufen = 5.0;
    farbe = floor(farbe * stufen + 0.5) / stufen;
    return vec4(farbe, 1.0);
}
